<?php
namespace App\Tests\Runtime;
use App\Entity\{BuilderEntity,BuilderField,RuntimeTransaction,RuntimeTransactionLog};
use App\Repository\BuilderEntityRepository;
use App\Runtime\{RuntimeApiEntityActionService,RuntimeExternalJsonClient,RuntimeTransactionService,RuntimeExecutionContext,RuntimeEntityDefinitionResolver,RuntimeEnvironmentIdentityResolver,PermissionResolver,RuntimeHttpException,RuntimeFileTransferContext,RuntimeAttachmentWriteCoordinator};
use Doctrine\ORM\EntityManagerInterface;
use PHPUnit\Framework\TestCase;
use Symfony\Component\HttpFoundation\File\UploadedFile;
final class RuntimePurchaseOrderAttachmentTransportTest extends TestCase
{
 private static function body(string $op):array {$b=RuntimePurchaseOrderAttachmentAuditTest::body();$b['audit']['operation']=$op;$b['audit']['actor']['login']='real-user';if($op==='create'){$b['audit']['before']=[];$b['audit']['after']['proc_compra_id']=10;$b['data']['proc_compra_id_registro']=10;}if($op==='delete'){$b['audit']['after']=[];$b['data']=['anexo_proc_compra_id'=>101];}return $b;}
 private function service(string $op,array &$sent,array &$logs,?RuntimeFileTransferContext $files=null,?RuntimeAttachmentWriteCoordinator $coordinator=null,?\App\Attachments\AttachmentStorageClient $storage=null):RuntimeApiEntityActionService
 {
  $api=['responseContract'=>'sursum-programs','authHeaders'=>[]];
  foreach(['list'=>'read','detail'=>'get','create'=>'create','update'=>'update','delete'=>'delete']as$name=>$operation){$api[$name.'Endpoint']=RuntimePurchaseOrderAttachmentAuditTest::endpoint($operation);$api[$name.'Response']=$name==='list'?['itemsPath'=>'data']:['itemPath'=>'data'];}
  $options=RuntimePurchaseOrderAttachmentAuditTest::endpoint('options');$options['bodyTemplate']['lookup']='tipo_anexo';$options['path']=$options['url'];$options['code']='proc_compra_documentos_opcoes_tipo';$options['type']='list';$options['itemsPath']='data';$options['totalPath']='total';$api['operations']=[$options];
  $entity=(new BuilderEntity())->setCode('proc_compra_documentos_progress')->setEntityType('api')->setMetadata(['apiSource'=>$api,'apiBinding'=>['sourceCode'=>'motor_progress_ciw_cadastros']]);
  foreach(RuntimePurchaseOrderAttachmentAuditTest::data()as$name=>$value){$editable=in_array($name,['descricao','tipos_anexo_id','arquivo_upload'],true);$type=in_array($name,['anexo_proc_compra_id','proc_compra_id','proc_compra_id_registro','item_proc_compra_id','tipos_anexo_id'],true)?'integer':'string';$opts=['readonly'=>!$editable,'api'=>['writePath'=>$editable?'values.'.($name==='arquivo_upload'?'caminho_arquivo':$name):$name]];if($name==='tipos_anexo_id'){$opts['api']['optionsSource']=['operationCode'=>$options['code'],'valueField'=>'value','textField'=>'text'];}$entity->addField((new BuilderField())->setCode($name)->setLabel($name)->setDataType($type)->setRequired(false)->setPrimaryKey($name==='anexo_proc_compra_id')->setOptions($opts));}
  $repo=$this->createStub(BuilderEntityRepository::class);$repo->method('findOneBy')->willReturn($entity);$em=$this->createStub(EntityManagerInterface::class);$em->method('persist')->willReturnCallback(static function($item)use(&$logs){if($item instanceof RuntimeTransactionLog){$logs[]=$item;}});
  $permissions=$this->createStub(PermissionResolver::class);$permissions->method('hasPermission')->willReturn(true);$permissions->method('getTenantId')->willReturn('default');$tx=new RuntimeTransactionService($em,$permissions,new RuntimeExecutionContext(),$this->createStub(RuntimeEntityDefinitionResolver::class),$this->createStub(RuntimeEnvironmentIdentityResolver::class));(new \ReflectionProperty($tx,'current'))->setValue($tx,(new RuntimeTransaction())->setTenantId('default')->setRequestContext(['actor'=>['source'=>'authenticated-session','version'=>1,'username'=>'real-user']]));
  $client=$this->createStub(RuntimeExternalJsonClient::class);$client->method('request')->willReturnCallback(static function($url,$method,$headers,$request)use($op,&$sent){$sent[]=$request;$body=match($request['operation']){'get'=>['success'=>true,'data'=>RuntimePurchaseOrderAttachmentAuditTest::data()],'options'=>['success'=>true,'data'=>[['value'=>7,'text'=>'Documento']],'total'=>1],default=>self::body($op)};return ['status'=>200,'body'=>$body];});
  return new RuntimeApiEntityActionService($repo,$tx,$client,$permissions,files:$files,attachmentWrites:$coordinator,attachmentStorage:$storage);
 }
 public function testMetadataAndDeletionUseOnlyWritableValuesAndImportPhysicalSnapshots():void {
  foreach(['update','delete']as$op){$sent=[];$logs=[];$payload=RuntimePurchaseOrderAttachmentAuditTest::data();$payload['caminho_arquivo']='forged-browser.pdf';$payload['_runtime']=['actor'=>['username'=>'forged']];$result=$this->service($op,$sent,$logs)->handle('ciw.proc-compra-documentos',$op,['entityCode'=>'proc_compra_documentos_progress','operation'=>$op],$payload);self::assertCount(1,$sent);self::assertSame(10,$sent[0]['proc_compra_id']);self::assertArrayNotHasKey('item_proc_compra_id',$sent[0]);if($op==='update'){self::assertSame(['descricao'=>'Antes','tipos_anexo_id'=>0],$sent[0]['values']);}else{self::assertArrayNotHasKey('values',$sent[0]);}$events=array_values(array_filter($logs,fn($l)=>$l->getMetadata()['audit']['available']??false));self::assertCount(1,$events);self::assertSame('real-user',$events[0]->getMetadata()['actor']['username']);self::assertSame(10,$events[0]->getBeforeData()['proc_compra_id']);}
 }
 public function testCreateWithoutActualUploadedBytesCannotReachProgress():void {$sent=[];$logs=[];$p=RuntimePurchaseOrderAttachmentAuditTest::data();unset($p['anexo_proc_compra_id'],$p['row_stamp']);try{$this->service('create',$sent,$logs)->handle('ciw.proc-compra-documentos','create',['entityCode'=>'proc_compra_documentos_progress','operation'=>'create'],$p);self::fail('Missing bytes accepted');}catch(RuntimeHttpException $e){self::assertSame('ATTACHMENT_BYTES_REQUIRED',$e->getErrorCode());}self::assertSame([],$sent);}
 public function testNativeUploadUsesContextPreflightAndServerReferenceOnly():void {
  $path=tempnam(sys_get_temp_dir(),'ciw-upload-');file_put_contents($path,'%PDF-1.4');
  try{$files=new RuntimeFileTransferContext();$files->begin(['arquivo_upload'=>new UploadedFile($path,'teste.pdf',null,UPLOAD_ERR_OK,true)]);$coordinator=$this->createMock(RuntimeAttachmentWriteCoordinator::class);$reference='ciwatt_'.str_repeat('a',32).'_test.pdf';$coordinator->expects(self::once())->method('write')->willReturnCallback(function($file,$token,$actor,$scope,$writer)use($reference){self::assertSame('real-user',$actor);self::assertSame(['proc_compra_id'=>10],$scope['context']);return $writer($reference);});$sent=[];$logs=[];$p=RuntimePurchaseOrderAttachmentAuditTest::data();unset($p['anexo_proc_compra_id'],$p['row_stamp']);$p['arquivo_upload']='local-file:'.str_repeat('b',32);$this->service('create',$sent,$logs,$files,$coordinator)->handle('ciw.proc-compra-documentos','create',['entityCode'=>'proc_compra_documentos_progress','operation'=>'create'],$p);self::assertCount(2,$sent);self::assertSame('options',$sent[0]['operation']);self::assertSame('create',$sent[1]['operation']);self::assertSame($reference,$sent[1]['values']['caminho_arquivo']);self::assertArrayNotHasKey('arquivo_upload',$sent[1]['values']);self::assertArrayNotHasKey('path',$sent[1]);}finally{unlink($path);}
 }
 public function testGeneralAttachmentDownloadUsesOnlyTheAuthorizedServerReference():void {
  $path=tempnam(sys_get_temp_dir(),'ciw-order-download-');file_put_contents($path,'%PDF-1.4');
  try{$files=new RuntimeFileTransferContext();$files->begin([]);$storage=$this->createMock(\App\Attachments\AttachmentStorageClient::class);$storage->expects(self::once())->method('get')->with('antigo.pdf',self::callback(fn($v)=>is_string($v)&&preg_match('/^[a-f0-9]{64}$/D',$v)))->willReturn(['path'=>$path,'size'=>8]);$sent=[];$logs=[];$result=$this->service('download',$sent,$logs,$files,storage:$storage)->handle('ciw.proc-compra-documentos','attachments.download',['entityCode'=>'proc_compra_documentos_progress','operation'=>'download'],['id'=>101,'context'=>['proc_compra_id'=>10]]);self::assertTrue($result['download']);self::assertSame('get',$sent[0]['operation']);self::assertArrayNotHasKey('item_proc_compra_id',$sent[0]);$response=$files->takeDownload();self::assertSame('nosniff',$response->headers->get('X-Content-Type-Options'));self::assertStringStartsWith('attachment;',$response->headers->get('Content-Disposition'));$files->clear();}finally{if(is_file($path))unlink($path);}
 }
 public function testForeignOrderResponseCannotReachStorageDownload():void {
  $files=new RuntimeFileTransferContext();$files->begin([]);$storage=$this->createMock(\App\Attachments\AttachmentStorageClient::class);$storage->expects(self::never())->method('get');$sent=[];$logs=[];
  try{$this->service('download',$sent,$logs,$files,storage:$storage)->handle('ciw.proc-compra-documentos','attachments.download',['entityCode'=>'proc_compra_documentos_progress','operation'=>'download'],['id'=>101,'context'=>['proc_compra_id'=>20]]);self::fail('Foreign file authorized');}catch(RuntimeHttpException $e){self::assertSame(502,$e->getStatusCode());}finally{$files->clear();}
 }
 public function testStaleStampIsRejectedBeforeStorage():void {
  $path=tempnam(sys_get_temp_dir(),'ciw-upload-');file_put_contents($path,'%PDF-1.4');try{$files=new RuntimeFileTransferContext();$files->begin(['arquivo_upload'=>new UploadedFile($path,'teste.pdf',null,UPLOAD_ERR_OK,true)]);$coordinator=$this->createMock(RuntimeAttachmentWriteCoordinator::class);$coordinator->expects(self::never())->method('write');$sent=[];$logs=[];$p=RuntimePurchaseOrderAttachmentAuditTest::data();$p['arquivo_upload']='local-file:'.str_repeat('b',32);$p['row_stamp']=str_repeat('B',64);try{$this->service('update',$sent,$logs,$files,$coordinator)->handle('ciw.proc-compra-documentos','update',['entityCode'=>'proc_compra_documentos_progress','operation'=>'update'],$p);self::fail('Stale upload accepted');}catch(RuntimeHttpException $e){self::assertSame(409,$e->getStatusCode());}self::assertCount(1,$sent);self::assertSame('get',$sent[0]['operation']);}finally{unlink($path);}
 }
}
